// Build a PII-free notification. Only ids, amounts, action and policy citations.
const j = $json;
const lines = [
  `Ticket ${j.ticket_id ?? '(none)'} - ${j.action}`,
  `Order ${j.order?.order_id} (${j.order?.product_name ?? ''})`,
  j.amount_cents ? `Amount: $${(j.amount_cents/100).toFixed(2)}` : null,
  j.refund_status ? `Refund: ${j.refund_status}${j.refund?.refund_id ? ' ' + j.refund.refund_id : ''}` : null,
  `Rationale: ${j.rationale ?? ''}`,
  (j.citations?.length ? `Policy: ${j.citations.join(', ')}` : null),
  `Trace/request id: ${j.request_id ?? ''}`
].filter(Boolean);
const text = lines.join('\n');
if (/[\w.+-]+@[\w-]+\.[\w.-]+/.test(text)) throw new Error('PII guard: email detected in notification');
return [{ json: { ...j, notification: text } }];
